{
  "risks": [
    {
      "condition": "Proposals must be submitted through the College's procurement portal as a single PDF of no more than 20 pages by 2026-12-01 12:00 UTC under REQ-0001.",
      "event": "The proposal exceeds 20 pages during final formatting or the upload experiences portal latency right before the 12:00 UTC deadline.",
      "effect": "The proposal is disqualified automatically without being evaluated.",
      "assumptions": [
        "The submission portal will remain responsive right up to the deadline."
      ],
      "owner_role": "Bid manager",
      "trigger": "The draft proposal reaches 18 pages one week before the submission date.",
      "responses": [
        "Enforce an 18-page limit on the master document.",
        "Upload a complete draft 24 hours prior to the deadline."
      ],
      "residual_exposure": "Minor formatting adjustments needed late; minor portal outage risk remains.",
      "evidence_src_ids": [
        "SRC-0015"
      ],
      "affects": [
        "REQ-0001"
      ]
    },
    {
      "condition": "The service must be live for students by 2027-01-11 under REQ-0012, but the College is closed from 2026-12-19 to 2027-01-04 with no staff available.",
      "event": "Integration testing and user acceptance are halted during the winter closure, leaving insufficient time after 2027-01-04 to verify the REST API integration before spring enrollment.",
      "effect": "Go-live is delayed or deployed with undetected integration faults, impacting spring enrollment.",
      "assumptions": [
        "College staff can perform remote verification during the closure."
      ],
      "owner_role": "Delivery lead",
      "trigger": "Integration testing is incomplete by 2026-12-15.",
      "responses": [
        "Complete staging integration tests prior to the 2026-12-19 closure.",
        "Agree on an emergency escalation path with College IT leads during the break."
      ],
      "residual_exposure": "Limited window for joint testing once the College reopens on 2027-01-04.",
      "evidence_src_ids": [
        "SRC-0032",
        "SRC-0013"
      ],
      "affects": [
        "REQ-0008",
        "REQ-0012",
        "1.2"
      ]
    },
    {
      "condition": "About 38,000 signed records are held in the current tool under REQ-0007, and migration is scheduled with high duration up to 30 days via work package 2.1.",
      "event": "Historical record migration encounters format discrepancies or partner delays, extending past the 2027-02-28 target date.",
      "effect": "Legacy signed documents remain inaccessible in the new system after the old tool contract ends on 2027-03-31.",
      "assumptions": [
        "Partner assistance will secure data export from the current hosted tool without friction."
      ],
      "owner_role": "Migration manager",
      "trigger": "Sample migration data extraction fails validation during initial sprints.",
      "responses": [
        "Initiate sample data extraction tests immediately upon contract award.",
        "Prioritize migration of the most recent two years of records first."
      ],
      "residual_exposure": "Older historical records might require manual retrieval if migration runs long.",
      "evidence_src_ids": [
        "SRC-0026",
        "SRC-0010",
        "SRC-0009"
      ],
      "affects": [
        "REQ-0007",
        "2.1"
      ]
    }
  ],
  "open_questions": [
    {
      "text": "Will the College provide technical database access schemas to accelerate the 38,000 record migration before the current tool contract expires?",
      "src_ids": [
        "SRC-0010",
        "SRC-0026"
      ]
    },
    {
      "text": "Are student disclosure blocks managed directly inside the student records system API, or must the e-signature service maintain a separate proxy control?",
      "src_ids": [
        "SRC-0032"
      ]
    }
  ]
}

